{
  "root_cause": "The navigation menu is incorrectly marked with aria-hidden=true when closed, which removes the links from the accessibility tree even though they are visually visible on desktop widths.",
  "repair_strategy": "Remove the line that sets aria-hidden on the menu in the Header.prototype.syncState method, allowing CSS to control visibility and ensuring the navigation links remain exposed to assistive technology.",
  "edits": [
    {
      "path": "src/govuk/components/header/header.js",
      "sha256": "33e331b7a1f44087522e22e90d1e295dbc0f915c8b8a82e8afd57a794d21fff4424",
      "before": "Header.prototype.syncState = function (isVisible) {\n  this.$menuButton.classList.toggle('govuk-header__menu-button--open', isVisible)\n  this.$menuButton.setAttribute('aria-expanded', isVisible)\n  this.$menu.setAttribute('aria-hidden', !isVisible)\n}",
      "after": "Header.prototype.syncState = function (isVisible) {\n  this.$menuButton.classList.toggle('govuk-header__menu-button--open', isVisible)\n  this.$menuButton.setAttribute('aria-expanded', isVisible)\n}"
    }
  ],
  "expected_accessibility_effect": "Navigation links will be exposed as links in the accessibility tree, allowing screen readers to announce them and keyboard users to focus them via Tab navigation.",
  "functional_risks": [
    "Removing aria-hidden may cause the menu to be announced when visually hidden via CSS on small screens, but the menu is hidden with display:none which already removes it from the accessibility tree, so risk is minimal."
  ],
  "verification_requirements": [
    "Verify that after the fix, the AX tree shows role='link' and name='Apply' for #nav-apply, and similarly for #nav-renew and #nav-rules.",
    "Confirm that the menu button's aria-expanded attribute toggles correctly when the menu button is clicked.",
    "Ensure that on mobile widths where the menu is toggled via the button, the menu opens and closes correctly and remains accessible when open.",
    "Check that keyboard focus order follows the visible header links (Apply, Renew a licence, Fishing rules) on desktop."
  ]
}
